"""specs_s200053.py - Sonnet-w2 family CC (generated by mkfamCC.py): 0x45c3a0, 0x41e290 (heap object or 0), 0x4ccbe0 record the SEH chain and the vtable word; the engine table flag byte at +0xbad is zero or not; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _gen(c):
    clear_hooks(c)
    seh_chain(c, c.rng.choice([0, 1, 2]))
    r = c.rng
    o = rnd(c, 0x100)
    p = r.choice([0, rnd(c, 0x40), rnd(c, 0x40)])
    hook_rec(c, 0x45c3a0, 3, ret=r.getrandbits(32), pop=12, this=True, side=_side(c, o))
    hook_rec(c, 0x41e290, 1, ret=p, pop=0, side=_side(c, o))
    hook_rec(c, 0x4ccbe0, 2, ret=r.getrandbits(32), pop=8, this=True, side=_side(c, o))
    eng = rnd(c, 0x1b00)
    c.emu.w32(0x70039c, eng)
    t = rnd(c, 0xc00)
    c.emu.w32(eng + 0x9b, t)
    c.emu.wbytes(t + 0xbad, bytes([r.choice([0, 0, 1, r.randrange(256)])]))
    return [o, r.getrandbits(32), r.getrandbits(32), r.getrandbits(32)]


S(0x447400, 'GUESS famCC 0x447400', 'thiscall', None, ret='eax', gen=_gen, note='batch200053')
S(0x447580, 'GUESS famCC 0x447580', 'thiscall', None, ret='eax', gen=_gen, note='batch200053')
